// === Tab: mySketch.js ===
/*
It is a 3D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Flip".

Interaction:
- Space Bar: Pause/Play
- Mouse Wheel: Forward / Backward in time
- Mouse Move: Camera Control
*/

const scale = Math.max(1, devicePixelRatio)
let theShader, moves=[0,0], wheelDelta = 0, wheelOffset = 0, pause = false, paused = 0, time = 0;

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/3012850/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function mouseMove() {
	if (!((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) return
	moves[0] += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) * scale
	moves[1] += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) * scale
}

function mouseWheel(e) {
	if (wheelDelta * e.deltaY < 0) {
		wheelDelta = e.deltaY
	} else {
		wheelDelta = lerp(wheelDelta, e.deltaY, 0.05)
	}
	wheelOffset += wheelDelta
}

function keyPressed(e) {
	if (e.key === " ") {
		if (!pause) {
			pause = true
		} else {
			pause = false
			paused = millis() - time
		}
	}
}

function draw() {
  mouseMove()
  shader(theShader)
  if (!pause) time = millis() - paused
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("move", moves)
  theShader.setUniform("wheel", [wheelDelta, wheelOffset])
  theShader.setUniform("time", time / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 move;
uniform vec2 wheel;
#define FC gl_FragCoord.xy
#define R resolution
#define T (5.5+time+wheel.y/1e3)
#define S smoothstep
#define MN min(R.x,R.y)
#define N normalize
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define bright vec3(.78,.79,.66)
#define dark vec3(.26,.34,.35)
float rnd(vec3 p) {
	p=fract(p*.1031);
	p+=dot(p,p.yzx+33.33);
	return fract((p.x+p.y)*p.z);
}
float noise(vec3 p) {
	vec3 i=floor(p), u=S(i,i+1.,p), k=vec3(1,0,0);
	return mix(	mix(	mix(	rnd(i+k.yyy), 
									rnd(i+k.xyy),u.x),
							mix(	rnd(i+k.yxy), 
									rnd(i+k.xxy),u.x),u.y),
					mix(	mix(	rnd(i+k.yyx), 
									rnd(i+k.xyx),u.x),
							mix(	rnd(i+k.yxx), 
									rnd(i+k.xxx),u.x),u.y),u.z);
}
float fbm(vec3 p) {
	float t=.0, a=1., h=.0;
	for (int i=0; i<5; i++) {
		t+=a*noise(p);
		p*=2.;
		a/=2.;
		h+=a;
	}
	return t/h;
}
vec3 render(vec2 uv, inout vec3 p, vec3 rd, out bool plane, out float glow) {
	vec3 col=vec3(0), lp=vec3(0,1,-10);
	lp.xz*=rot(-T*.5); // the daylight cycle
	bool hit; float dd;
	for (float i; i++<400.;) {
		float a=length(p)-1., b=p.y+1.1, sun=(length(p-lp)-.2),
		d=min(min(a,b),sun);
		glow+=.05/(.05+sun*sun*80.);
		if (abs(d)<1e-3) {
			hit=!hit;
			plane=b<a && b<sun;
			break;
		}
		if (d>100.) break;
		p+=rd*d;
		dd+=d;
	}
	if (hit) {
		vec3 n=N(p);
		vec3 l=N(lp-p);
		if (!plane) {
			float dif=clamp(dot(l,n),.0,1.);
			p.xz*=rot(-T*.2);
			float f=fbm(p*4.+33.33+fbm(p*8.+fbm(p.yzx*12.+fbm(p.zxy*21.))));
			col=mix(dark,bright,mix(-.3,.8,sqrt(dif)*f));
			col=mix(col*col*f,col,S(-.3,.7,dif*f));
			col+=.2*pow(max(.0,dot(reflect(rd,n),l)),9.);
		} else {
			n=vec3(0,1,0);
			float dif=clamp(dot(l,n),.0,1.);
			col+=dif*clamp((length(p+n*.25)-1.)/.25,.0,1.);
		}
	}
	return col;
}
vec3 dir(vec2 uv, vec3 p, vec3 t, float z) {
	vec3 up=vec3(0,1,0),
	f=N(t-p),
	r=N(cross(up,f)),
	u=N(cross(f,r));
	return mat3(r,u,f)*N(vec3(uv,z));
}
void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(0),
	p=vec3(-move.x*6.3/MN,3.-exp(cos(T*.25-move.y*6.3/MN)),-3.-exp(cos(T*.125-move.y*6.3/MN))),
	rd=dir(uv,p,vec3(0),1.2);
	bool plane; float glow, refl;
	col+=render(uv,p,rd,plane,glow);
	// render reflective plane
	if (plane) {
		vec3 n=vec3(0,1,0);
		rd=reflect(rd,n);
		p+=n*5e-2;
		col=mix(col,.8*render(uv,p,rd,plane,refl),.9*pow(clamp(1.+dot(rd,n),.0,1.),5.));
	}
	col+=vec3(1,.8,.7)*pow(max(glow,refl),.4);
	col=max(col,.08);
	vec2 c=FC/R;
	c*=1.-c.yx;
	float v=c.x*c.y*25.;
	col=mix(vec3(0),col,pow(v,.25));
	col-=.002*(sin(uv.x*1600.)+sin(uv.y*1200.));
	O=vec4(col,1);
}

